 p_id=>wwv_flow_imp.id(10511099995033801)
,p_plug_name=>unistr('Distribui\00E7\00E3o dos Pacientes por Faixa Et\00E1ria')
,p_static_id=>unistr('distribui\00E7\00E3o-dos-pacientes-por-faixa-et\00E1ria')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    FAIXA_ETARIA,',
'    COUNT(*) AS QUANTIDADE',
'FROM (',
'    SELECT',
'        CASE',
'            WHEN P.IDADE < 18 THEN ''Menor de 18''',
'            WHEN P.IDADE BETWEEN 18 AND 39 THEN ''18 a 39 anos''',
'            WHEN P.IDADE BETWEEN 40 AND 59 THEN ''40 a 59 anos''',
'            WHEN P.IDADE BETWEEN 60 AND 79 THEN ''60 a 79 anos''',
'            WHEN P.IDADE >= 80 THEN ''80 anos ou mais''',
unistr('            ELSE ''N\00E3o informado'''),
'        END AS FAIXA_ETARIA,',
'',
'        CASE',
'            WHEN P.IDADE < 18 THEN 1',
'            WHEN P.IDADE BETWEEN 18 AND 39 THEN 2',
'            WHEN P.IDADE BETWEEN 40 AND 59 THEN 3',
'            WHEN P.IDADE BETWEEN 60 AND 79 THEN 4',
'            WHEN P.IDADE >= 80 THEN 5',
'            ELSE 6',
'        END AS ORDEM',
'',
'    FROM ADMIN.T_INTERNACOES I',
'',
'    JOIN ADMIN.T_PACIENTES P',
'        ON P.ID_PACIENTE = I.ID_PACIENTE',
'',
'    WHERE UPPER(I.STATUS) = ''INTERNADO''',
')',
'GROUP BY',
'    FAIXA_ETARIA,',
'    ORDEM',
'',
'ORDER BY ORDEM;'))
,p_plug_source_type=>'NATIVE_JET_CHART'
,p_created_on=>wwv_flow_imp.dz('20260911170023Z')
,p_updated_on=>wwv_flow_imp.dz('20260911170241Z')
,p_created_by=>'DATACROSS_APP'
,p_updated_by=>'DATACROSS_APP'
);
