,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    SEXO AS LABEL,',
'    COUNT(*) AS VALOR',
'FROM (',
'    SELECT',
'        CASE',
'            WHEN LOWER(TRIM(P.SEXO)) IN (''m'', ''masculino'')',
'                THEN ''Masculino''',
'',
'            WHEN LOWER(TRIM(P.SEXO)) IN (''f'', ''feminino'')',
'                THEN ''Feminino''',
'',
unistr('            ELSE ''N\00E3o informado'''),
'        END AS SEXO',
'    FROM ADMIN.T_INTERNACOES I',
'',
'    JOIN ADMIN.T_PACIENTES P',
'        ON P.ID_PACIENTE = I.ID_PACIENTE',
'',
'    WHERE UPPER(I.STATUS) = ''INTERNADO''',
')',
'GROUP BY SEXO',
'ORDER BY',
'    CASE SEXO',
'        WHEN ''Masculino'' THEN 1',
'        WHEN ''Feminino'' THEN 2',
'        ELSE 3',
'    END;'))
,p_items_value_column_name=>'VALOR'
,p_items_label_column_name=>'LABEL'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>true
,p_items_label_position=>'auto'
