wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(9480431301445305)
,p_chart_id=>wwv_flow_imp.id(9480300430445304)
,p_static_id=>'employees'
,p_seq=>10
,p_name=>'Employees'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    PATOLOGIA AS LABEL,',
'    SUM(TOTAL_INTERNACOES) AS VALUE',
'FROM (',
'    SELECT',
'        CASE',
'            WHEN LOWER(DOENCA_DETECTADA) IN (',
'                ''avc_isquemico'',',
'                ''avc_hemorragico''',
'            )',
'            THEN ''AVC''',
'',
'            WHEN LOWER(DOENCA_DETECTADA) = ''pneumonia''',
'            THEN ''Pneumonia''',
'',
'            WHEN LOWER(DOENCA_DETECTADA) =',
unistr('                 ''infec\00E7\00E3o do trato urin\00E1rio (itu)'''),
unistr('            THEN ''Infec\00E7\00E3o do trato urin\00E1rio (ITU)'''),
'',
'            ELSE DOENCA_DETECTADA',
'        END AS PATOLOGIA,',
'',
'        TOTAL_INTERNACOES',
'    FROM V_INDICADORES',
')',
'GROUP BY PATOLOGIA',
'ORDER BY VALUE DESC'))
,p_items_value_column_name=>'VALUE'
,p_items_label_column_name=>'LABEL'
,p_items_label_rendered=>true
,p_items_label_position=>'auto'
,p_items_label_display_as=>'LABEL'
,p_created_on=>wwv_flow_imp.dz('20260908151854Z')
