,p_updated_by=>'DATACROSS_APP'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10511540823033806)
,p_plug_name=>unistr('Perman\00EAncia M\00E9dia por Patologia')
,p_static_id=>unistr('perman\00EAncia-m\00E9dia-por-patologia')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    PATOLOGIA,',
'    ROUND(AVG(TEMPO_PERMANENCIA_DIAS), 1) AS MEDIA_DIAS',
'FROM (',
'    SELECT',
'        CASE',
'            WHEN LOWER(D.DOENCA_DETECTADA)',
'                 IN (''avc_isquemico'', ''avc_hemorragico'')',
'                THEN ''AVC''',
'',
'            WHEN LOWER(D.DOENCA_DETECTADA) = ''pneumonia''',
'                THEN ''Pneumonia''',
'',
'            WHEN LOWER(D.DOENCA_DETECTADA) LIKE ''%trato urin%''',
'                THEN ''ITU''',
'',
'            ELSE INITCAP(',
'                REPLACE(D.DOENCA_DETECTADA, ''_'', '' '')',
'            )',
'        END AS PATOLOGIA,',
'',
'        I.TEMPO_PERMANENCIA_DIAS',
'',
'    FROM ADMIN.T_INTERNACOES I',
'',
'    JOIN ADMIN.T_DIAGNOSTICOS D',
'        ON D.CID = I.CID',
'',
'    WHERE UPPER(I.STATUS) = ''INTERNADO''',
')',
'GROUP BY PATOLOGIA',
'ORDER BY MEDIA_DIAS DESC;'))
,p_plug_source_type=>'NATIVE_JET_CHART'
,p_created_on=>wwv_flow_imp.dz('20260911170902Z')
,p_updated_on=>wwv_flow_imp.dz('20260913230040Z')
,p_created_by=>'DATACROSS_APP'
,p_updated_by=>'DATACROSS_APP'
);
