,p_legend_rendered=>'off'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(options) {',
'',
'    options.dataFilter = function(data) {',
'',
'        if (data.series && data.series.length > 0) {',
'',
'            var cores = [',
'                "#4E79A7",',
'                "#F28E2B",',
'                "#59A14F",',
'                "#E15759",',
'                "#B07AA1"',
'            ];',
'',
'            if (data.series[0].items) {',
'                data.series[0].items.forEach(function(item, index) {',
'                    item.color = cores[index % cores.length];',
'                });',
'            }',
'        }',
'',
'        return data;',
'    };',
'',
'    options.tooltip = {',
'        renderer: function(context) {',
'',
'            var tooltip = document.createElement("div");',
'',
'            var categoria =',
'                context.group ||',
'                context.label ||',
'                "";',
'',
'            var valor =',
'                context.value;',
'',
'            if (valor === undefined || valor === null) {',
'                valor = context.data;',
'            }',
'',
'            if (valor === undefined || valor === null) {',
'                valor = context.y;',
'            }',
'',
'            tooltip.innerHTML =',
'                "<strong>" + categoria + "</strong><br>" +',
'                "Quantidade: <strong>" + (valor ?? "") + "</strong>";',
'',
'            return {',
'                insert: tooltip',
'            };',
'        }',
'    };',
'',
'    return options;',
'}'))
,p_created_on=>wwv_flow_imp.dz('20260911170902Z')
,p_updated_on=>wwv_flow_imp.dz('20260913230040Z')
,p_created_by=>'DATACROSS_APP'
,p_updated_by=>'DATACROSS_APP'
);
