'    TO_CHAR(',
'        SUM(TOTAL_INTERNACOES),',
'        ''FM999G999G990'',',
'        ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'    ) AS VALOR,',
'    1 AS ORDEM',
'FROM V_INDICADORES',
'',
'UNION ALL',
'',
'SELECT',
'    ''Pacientes Internados Atualmente'',',
'    TO_CHAR(',
'        SUM(TOTAL_INTERNADOS),',
'        ''FM999G999G990'',',
'        ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'    ),',
'    2',
'FROM V_INDICADORES',
'',
'UNION ALL',
'',
'SELECT',
unistr('    ''Perman\00EAncia M\00E9dia'','),
'    TO_CHAR(',
'        ROUND(',
'            SUM(MEDIA_PERMANENCIA_DIAS * TOTAL_INTERNACOES)',
'            / NULLIF(SUM(TOTAL_INTERNACOES), 0),',
'            1',
'        ),',
'        ''FM999G990D0'',',
'        ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'    ) || '' dias'',',
'    3',
'FROM V_INDICADORES',
'',
'ORDER BY ORDEM;'))
