 p_id=>wwv_flow_imp.id(10620880989607728)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Sincronizar Prontu\00E1rio com Tabelas Normalizadas')
,p_static_id=>unistr('sincronizar-prontu\00E1rio-com-tabelas-normalizadas')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    -- 1. PACIENTE',
'    INSERT INTO ADMIN.T_PACIENTES (',
'        ID_PACIENTE,',
'        IDADE,',
'        SEXO,',
'        MUNICIPIO_REGIAO_DE_RESIDENCIA',
'    )',
'    VALUES (',
'        :P2_ID_PACIENTE,',
'        :P2_IDADE,',
'        :P2_SEXO,',
'        :P2_MUNICIPIO_REGIAO_DE_RESIDENCIA',
'    );',
'',
unistr('    -- 2. DIAGN\00D3STICO'),
'    BEGIN',
'        INSERT INTO ADMIN.T_DIAGNOSTICOS (',
'            CID,',
'            DOENCA_DETECTADA',
'        )',
'        VALUES (',
'            :P2_CID,',
'            :P2_DOENCA_DETECTADA',
'        );',
'    EXCEPTION',
'        WHEN DUP_VAL_ON_INDEX THEN',
'            NULL;',
'    END;',
'',
unistr('    -- 3. INTERNA\00C7\00C3O'),
'    INSERT INTO ADMIN.T_INTERNACOES (',
'        ID_INTERNACAO,',
'        ID_PACIENTE,',
'        ID_HOSPITAL,',
'        DATA_INTERNACAO,',
'        DATA_SAIDA,',
'        STATUS,',
'        TEMPO_PERMANENCIA_DIAS,',
'        TIPO_INTERNACAO,',
'        SETOR_UNIDADE,',
'        CID,',
'        VALOR_DIARIA_LEITO',
'    )',
'    VALUES (',
'        :P2_ID_INTERNACAO,',
'        :P2_ID_PACIENTE,',
'        :P2_ID_DO_HOSPITAL,',
'        :P2_DATA_DE_INTERNACAO,',
'        NULL,',
'        :P2_STATUS,',
'        :P2_TEMPO_DE_PERMANENCIA_DIAS,',
'        :P2_TIPO_DE_INTERNACAO,',
'        :P2_SETOR_UNIDADE,',
'        :P2_CID,',
'        CASE :P2_SETOR_UNIDADE',
'            WHEN ''enfermaria'' THEN 150',
'            WHEN ''uni-avc'' THEN 150',
'            WHEN ''semi-intensiva'' THEN 300',
'            WHEN ''UTI'' THEN 600',
'            ELSE NULL',
'        END',
'    );',
'',
'    -- 4. SINAIS VITAIS',
'    INSERT INTO ADMIN.T_SINAIS_VITAIS (',
'        ID_INTERNACAO,',
'        FC,',
'        FR,',
'        PAS,',
'        TEMP_AXILAR,',
'        SPO2,',
'        NIVEL_CONSCIENCIA,',
'        DIURESE,',
'        GLICEMIA_CAPILAR',
'    )',
'    VALUES (',
'        :P2_ID_INTERNACAO,',
'        :P2_FC,',
'        :P2_FR,',
'        :P2_PAS,',
'        :P2_TEMP_AXILAR,',
'        :P2_SPO2,',
'        :P2_NIVEL_DE_CONSCIENCIA,',
'        :P2_DIURESE,',
'        :P2_GLICEMIA_CAPILAR',
'    );',
'',
'    -- 5. DISPOSITIVOS',
'    INSERT INTO ADMIN.T_DISPOSITIVOS (',
'        ID_INTERNACAO,',
'        SONDA_VESICAL_DE_DEMORA,',
'        SONDA_NASOGASTRICA,',
'        SONDA_NASOENTERAL,',
'        CATETER_DE_O2,',
'        INTUBACAO_OROTRAQUEAL,',
'        VENTILACAO_MECANICA,',
'        CATETER_VENOSO_CENTRAL,',
'        PICC,',
'        CATETER_VENOSO_PERIFERICO',
'    )',
'    VALUES (',
'        :P2_ID_INTERNACAO,',
'        :P2_SONDA_VESICAL_DE_DEMORA,',
'        :P2_SONDA_NASOGASTRICA,',
'        :P2_SONDA_NASOENTERAL,',
'        :P2_CATETER_DE_O2,',
'        :P2_INTUBACAO_OROTRAQUEAL,',
'        :P2_VENTILACAO_MECANICA,',
'        :P2_CATETER_VENOSO_CENTRAL,',
'        :P2_CATETER_VENOSO_CENTRAL_DE_INSERCAO_PERIFERICA_PICC,',
'        :P2_CATETER_VENOSO_PERIFERICO',
'    );',
'',
'    -- 6. TRATAMENTOS E EXAMES',
'    INSERT INTO ADMIN.T_TRATAMENTOS_EXAMES (',
'        ID_INTERNACAO,',
'        TC_POSITIVO_PARA_AVC,',
'        EEG_POSITIVO_PARA_AVC,',
'        ANTIBIOTICO,',
'        DATA_INICIO_ATB,',
'        DURACAO_ATB_DIAS,',
'        PADRAO_TOMOGRAFIA,',
'        ETIOLOGIA_PNEUMONIA,',
'        TRATAMENTO_ETIOLOGICO,',
'        UROCULTURA',
'    )',
'    VALUES (',
'        :P2_ID_INTERNACAO,',
'        :P2_TC_POSITIVO_PARA_AVC,',
'        :P2_EEG_POSITIVO_PARA_AVC,',
'        :P2_ANTIBIOTICO,',
'        CASE',
'            WHEN :P2_DATA_DE_INICIO_ATB IS NOT NULL',
'            THEN TO_DATE(:P2_DATA_DE_INICIO_ATB, ''DD/MM/YYYY'')',
'            ELSE NULL',
'        END,',
'        :P2_DURACAO_ATB,',
'        :P2_PADRAO_TOMOGRAFIA,',
'        :P2_ETIOLOGIA_PNEUMONIA,',
'        :P2_TRATAMENTO_ETIOLOGICO,',
'        :P2_UROCULTURA',
'    );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>10620880989607728
,p_created_on=>wwv_flow_imp.dz('20260911212122Z')
,p_updated_on=>wwv_flow_imp.dz('20260911220529Z')
,p_created_by=>'DATACROSS_APP'
,p_updated_by=>'DATACROSS_APP'
);
end;
