,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    I.ID_INTERNACAO,',
'    I.ID_PACIENTE,',
'    P.IDADE,',
'    P.SEXO,',
'    H.NOME_HOSPITAL,',
'    DG.DOENCA_DETECTADA AS PATOLOGIA,',
'    I.SETOR_UNIDADE,',
'    I.DATA_INTERNACAO,',
'    I.TEMPO_PERMANENCIA_DIAS,',
'',
unistr('    /* Mant\00E9m o nome antigo para n\00E3o quebrar o APEX */'),
'    DC.SCORE_ALTA AS SCORE_FINAL,',
'',
'    /* PRIORIDADE DATACROSS */',
'    CASE',
'        WHEN DC.DESTINO_SUGERIDO IN (',
'            ''Apto para alta'',',
unistr('            ''Apto para transfer\00EAncia'''),
'        )',
'        THEN ''Alta''',
'',
'        WHEN DC.DESTINO_SUGERIDO =',
'             ''Reavaliar em 24 horas''',
unistr('        THEN ''M\00E9dia'''),
'',
'        WHEN DC.DESTINO_SUGERIDO =',
'             ''Permanece internado''',
'        THEN ''Baixa''',
'',
unistr('        ELSE ''Sem classifica\00E7\00E3o'''),
'    END AS PRIORIDADE_DATACROSS,',
'',
unistr('    /* BLOQUEIO CL\00CDNICO */'),
'    DC.BLOQUEIO_ALTA AS BLOQUEIO,',
'',
'    CASE',
'        WHEN DC.BLOQUEIO_ALTA = 1',
'        THEN ''Sim''',
unistr('        ELSE ''N\00E3o'''),
'    END AS BLOQUEIO_CLINICO,',
'',
'    DC.MOTIVO_BLOQUEIO_ALTA AS MOTIVO_BLOQUEIO,',
'',
unistr('    /* Mant\00E9m a classifica\00E7\00E3o antiga dispon\00EDvel */'),
'    DC.CLASSIFICACAO_ALTA AS CLASSIFICACAO_FINAL,',
'',
'    /* ==============================',
unistr('       NOVAS INFORMA\00C7\00D5ES'),
'       ============================== */',
'',
'    DC.DESTINO_SUGERIDO,',
'',
'    DC.NECESSIDADE_CONTINUIDADE_HOSPITALAR,',
'',
'    DC.MOTIVO_CONTINUIDADE_HOSPITALAR,',
'',
'    DC.SCORE_TRANSFERENCIA,',
'',
'    DC.CLASSIFICACAO_TRANSFERENCIA,',
'',
'    DC.ALERTA_CRITICO_TRANSFERENCIA,',
'',
'    DC.MOTIVO_ALERTA_TRANSFERENCIA,',
'',
'    DC.SAIDA_TRANSFERENCIA,',
'',
'    DC.SUPORTE_TRANSFERENCIA,',
'',
'    DC.JUSTIFICATIVA_DESTINO,',
'',
'    I.STATUS',
'',
'FROM ADMIN.T_INTERNACOES I',
'',
'JOIN ADMIN.T_PACIENTES P',
'    ON P.ID_PACIENTE = I.ID_PACIENTE',
'',
'JOIN ADMIN.T_HOSPITAIS H',
'    ON H.ID_HOSPITAL = I.ID_HOSPITAL',
'',
'JOIN ADMIN.T_DIAGNOSTICOS DG',
'    ON DG.CID = I.CID',
'',
'LEFT JOIN WKSP_DATACROSS.V_DECISAO_DATACROSS DC',
'    ON DC.ID_INTERNACAO = I.ID_INTERNACAO',
'',
'WHERE UPPER(TRIM(I.STATUS)) = ''INTERNADO''',
'',
'  AND H.NOME_HOSPITAL =',
'      ''hospital_universitario_sr._dolphin_sakila''',
'',
'ORDER BY',
'',
unistr('    /* Primeiro os aptos para transfer\00EAncia */'),
'    CASE',
'        WHEN DC.DESTINO_SUGERIDO =',
unistr('             ''Apto para transfer\00EAncia'''),
'        THEN 1',
'',
'        /* Depois aptos para alta */',
'        WHEN DC.DESTINO_SUGERIDO =',
'             ''Apto para alta''',
'        THEN 2',
'',
unistr('        /* Depois reavalia\00E7\00E3o */'),
'        WHEN DC.DESTINO_SUGERIDO =',
'             ''Reavaliar em 24 horas''',
'        THEN 3',
'',
unistr('        /* Depois perman\00EAncia */'),
'        WHEN DC.DESTINO_SUGERIDO =',
'             ''Permanece internado''',
'        THEN 4',
'',
'        ELSE 5',
'    END,',
'',
'    I.TEMPO_PERMANENCIA_DIAS DESC,',
'',
'    DC.SCORE_ALTA DESC;'))
,p_plug_source_type=>'NATIVE_IR'
