unistr('        WHEN ''nao'' THEN ''N\00E3o'''),
unistr('        WHEN ''n\00E3o'' THEN ''N\00E3o'''),
'        ELSE INITCAP(REPLACE(C.HIPERTENSAO, ''_'', '' ''))',
'    END AS VALOR,',
'',
'    1 AS ORDEM',
'',
'FROM ADMIN.T_INTERNACOES I',
'JOIN ADMIN.T_COMORBIDADES C',
'    ON C.ID_PACIENTE = I.ID_PACIENTE',
'',
'WHERE I.ID_INTERNACAO = :P4_ID_INTERNACAO',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
'    ''Diabetes'',',
'',
'    CASE LOWER(TRIM(C.DIABETES))',
'        WHEN ''sim'' THEN ''Sim''',
unistr('        WHEN ''nao'' THEN ''N\00E3o'''),
unistr('        WHEN ''n\00E3o'' THEN ''N\00E3o'''),
'        ELSE INITCAP(REPLACE(C.DIABETES, ''_'', '' ''))',
'    END,',
'',
'    2',
'',
'FROM ADMIN.T_INTERNACOES I',
'JOIN ADMIN.T_COMORBIDADES C',
'    ON C.ID_PACIENTE = I.ID_PACIENTE',
'',
'WHERE I.ID_INTERNACAO = :P4_ID_INTERNACAO',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
'    ''Sequela de AVC'',',
'',
'    CASE LOWER(TRIM(C.SEQUELA_DE_AVC))',
'        WHEN ''sim'' THEN ''Sim''',
unistr('        WHEN ''nao'' THEN ''N\00E3o'''),
unistr('        WHEN ''n\00E3o'' THEN ''N\00E3o'''),
