'',
'WHERE I.ID_INTERNACAO = :P4_ID_INTERNACAO',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
unistr('    ''Insufici\00EAncia Card\00EDaca'','),
'',
'    CASE LOWER(TRIM(C.INSUFICIENCIA_CARDIACA))',
'        WHEN ''sim'' THEN ''Sim''',
unistr('        WHEN ''nao'' THEN ''N\00E3o'''),
unistr('        WHEN ''n\00E3o'' THEN ''N\00E3o'''),
'        ELSE INITCAP(REPLACE(C.INSUFICIENCIA_CARDIACA, ''_'', '' ''))',
'    END,',
'',
'    5',
'',
'FROM ADMIN.T_INTERNACOES I',
'JOIN ADMIN.T_COMORBIDADES C',
'    ON C.ID_PACIENTE = I.ID_PACIENTE',
'',
'WHERE I.ID_INTERNACAO = :P4_ID_INTERNACAO',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
'    ''DRC'',',
'',
'    CASE LOWER(TRIM(C.DRC))',
'        WHEN ''sim'' THEN ''Sim''',
unistr('        WHEN ''nao'' THEN ''N\00E3o'''),
unistr('        WHEN ''n\00E3o'' THEN ''N\00E3o'''),
'        ELSE INITCAP(REPLACE(C.DRC, ''_'', '' ''))',
'    END,',
'',
'    6',
'',
'FROM ADMIN.T_INTERNACOES I',
'JOIN ADMIN.T_COMORBIDADES C',
'    ON C.ID_PACIENTE = I.ID_PACIENTE',
'',
'WHERE I.ID_INTERNACAO = :P4_ID_INTERNACAO',
'',
'',
'UNION ALL',
'',
'',
