'',
'    CASE LOWER(TRIM(C.NEOPLASIA))',
'        WHEN ''sim'' THEN ''Sim''',
unistr('        WHEN ''nao'' THEN ''N\00E3o'''),
unistr('        WHEN ''n\00E3o'' THEN ''N\00E3o'''),
'        ELSE INITCAP(REPLACE(C.NEOPLASIA, ''_'', '' ''))',
'    END,',
'',
'    8',
'',
'FROM ADMIN.T_INTERNACOES I',
'JOIN ADMIN.T_COMORBIDADES C',
'    ON C.ID_PACIENTE = I.ID_PACIENTE',
'',
'WHERE I.ID_INTERNACAO = :P4_ID_INTERNACAO',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
'    ''DPOC'',',
'',
'    CASE LOWER(TRIM(C.DPOC))',
'        WHEN ''sim'' THEN ''Sim''',
unistr('        WHEN ''nao'' THEN ''N\00E3o'''),
unistr('        WHEN ''n\00E3o'' THEN ''N\00E3o'''),
'        ELSE INITCAP(REPLACE(C.DPOC, ''_'', '' ''))',
'    END,',
'',
'    9',
'',
'FROM ADMIN.T_INTERNACOES I',
'JOIN ADMIN.T_COMORBIDADES C',
'    ON C.ID_PACIENTE = I.ID_PACIENTE',
'',
'WHERE I.ID_INTERNACAO = :P4_ID_INTERNACAO',
'',
'ORDER BY ORDEM;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
