wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(10050416263253931)
,p_name=>'Dados do Paciente'
,p_static_id=>'dados-do-paciente_1'
,p_parent_plug_id=>wwv_flow_imp.id(10048665198253913)
,p_template=>2074200852440250129
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    I.ID_INTERNACAO,',
'    I.ID_PACIENTE,',
'    P.IDADE,',
'',
'    CASE',
'        WHEN LOWER(TRIM(P.SEXO)) IN (''m'', ''masculino'') THEN ''Masculino''',
'        WHEN LOWER(TRIM(P.SEXO)) IN (''f'', ''feminino'') THEN ''Feminino''',
'        ELSE INITCAP(REPLACE(P.SEXO, ''_'', '' ''))',
'    END AS SEXO,',
'',
'    INITCAP(',
'        REPLACE(P.MUNICIPIO_REGIAO_DE_RESIDENCIA, ''_'', '' '')',
'    ) AS MUNICIPIO,',
'',
'    CASE',
'        WHEN H.NOME_HOSPITAL =',
'             ''hospital_universitario_sr._dolphin_sakila''',
unistr('        THEN ''Hospital Universit\00E1rio Sr. Dolphin Sakila'''),
'',
'        ELSE INITCAP(',
'            REPLACE(H.NOME_HOSPITAL, ''_'', '' '')',
'        )',
'    END AS NOME_HOSPITAL,',
'',
'    INITCAP(',
'        REPLACE(H.NIVEL_ATENCAO, ''_'', '' '')',
'    ) AS NIVEL_ATENCAO,',
'',
'    INITCAP(',
'        REPLACE(H.REGIAO_HOSPITAL, ''_'', '' '')',
'    ) AS REGIAO_HOSPITAL,',
'',
'    I.CID,',
'',
'    CASE',
'        WHEN LOWER(DG.DOENCA_DETECTADA) = ''avc_isquemico''',
unistr('        THEN ''AVC Isqu\00EAmico'''),
'',
'        WHEN LOWER(DG.DOENCA_DETECTADA) = ''avc_hemorragico''',
unistr('        THEN ''AVC Hemorr\00E1gico'''),
'',
'        WHEN LOWER(DG.DOENCA_DETECTADA) LIKE ''%trato urin%''',
unistr('        THEN ''Infec\00E7\00E3o do Trato Urin\00E1rio'''),
'',
'        WHEN LOWER(DG.DOENCA_DETECTADA) = ''pneumonia''',
'        THEN ''Pneumonia''',
'',
'        ELSE INITCAP(',
'            REPLACE(DG.DOENCA_DETECTADA, ''_'', '' '')',
'        )',
'    END AS PATOLOGIA,',
'',
'    I.DATA_INTERNACAO,',
'    I.TEMPO_PERMANENCIA_DIAS,',
'',
'    INITCAP(',
'        REPLACE(I.TIPO_INTERNACAO, ''_'', '' '')',
'    ) AS TIPO_INTERNACAO,',
'',
'    INITCAP(',
'        REPLACE(I.SETOR_UNIDADE, ''_'', '' '')',
'    ) AS SETOR_UNIDADE,',
'',
'    CASE',
'        WHEN LOWER(TRIM(I.STATUS)) = ''internado''',
'        THEN ''Internado''',
'',
'        WHEN LOWER(TRIM(I.STATUS)) = ''alta''',
'        THEN ''Alta''',
'',
'        WHEN LOWER(TRIM(I.STATUS)) = ''obito''',
unistr('        THEN ''\00D3bito'''),
'',
'        ELSE INITCAP(',
'            REPLACE(I.STATUS, ''_'', '' '')',
'        )',
'    END AS STATUS,',
'',
unistr('    /* SCORE \00DANICO */'),
'    DC.SCORE_ALTA AS SCORE,',
'',
'    /* BLOQUEIO */',
'    CASE',
'        WHEN DC.BLOQUEIO_ALTA = 1',
'        THEN ''Sim''',
unistr('        ELSE ''N\00E3o'''),
'    END AS BLOQUEIO_CLINICO,',
'',
unistr('    /* DECIS\00C3O FINAL */'),
'    DC.DESTINO_SUGERIDO,',
'',
'    /* CONTINUIDADE HOSPITALAR */',
'    DC.NECESSIDADE_CONTINUIDADE_HOSPITALAR,',
'',
'    DC.MOTIVO_CONTINUIDADE_HOSPITALAR,',
'',
unistr('    /* ALERTA DE TRANSFER\00CANCIA */'),
'    CASE',
'        WHEN DC.ALERTA_CRITICO_TRANSFERENCIA = 1',
'        THEN ''Sim''',
unistr('        ELSE ''N\00E3o'''),
'    END AS ALERTA_CRITICO_TRANSFERENCIA',
'',
'',
'FROM ADMIN.T_INTERNACOES I',
'',
'JOIN ADMIN.T_PACIENTES P',
'    ON P.ID_PACIENTE = I.ID_PACIENTE',
'',
'JOIN ADMIN.T_HOSPITAIS H',
'    ON H.ID_HOSPITAL = I.ID_HOSPITAL',
'',
'JOIN ADMIN.T_DIAGNOSTICOS DG',
'    ON DG.CID = I.CID',
'',
'LEFT JOIN WKSP_DATACROSS.V_DECISAO_DATACROSS DC',
'    ON DC.ID_INTERNACAO = I.ID_INTERNACAO',
'',
'WHERE I.ID_INTERNACAO = :P4_ID_INTERNACAO;'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20260910145320Z')
,p_updated_on=>wwv_flow_imp.dz('20260913212625Z')
,p_created_by=>'DATACROSS_APP'
,p_updated_by=>'DATACROSS_APP'
);
