wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10212458801682503)
,p_plug_name=>'Dispositivos e Suporte'
,p_static_id=>'dispositivos'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>70
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH DADOS AS (',
'    SELECT',
'        X.*,',
'',
'        CASE',
'            WHEN LOWER(D.DOENCA_DETECTADA)',
'                 IN (''avc_isquemico'',''avc_hemorragico'')',
'                THEN ''AVC''',
'            WHEN LOWER(D.DOENCA_DETECTADA) LIKE ''%trato urin%''',
'                THEN ''ITU''',
'            WHEN LOWER(D.DOENCA_DETECTADA) = ''pneumonia''',
'                THEN ''PNEUMONIA''',
'        END AS PATOLOGIA,',
'',
'        (',
'            CASE WHEN LOWER(X.SONDA_NASOGASTRICA) = ''sim'' THEN 1 ELSE 0 END +',
'            CASE WHEN LOWER(X.SONDA_NASOENTERAL) = ''sim'' THEN 1 ELSE 0 END +',
'            CASE WHEN LOWER(X.CATETER_VENOSO_CENTRAL) = ''sim'' THEN 1 ELSE 0 END +',
'            CASE WHEN LOWER(X.PICC) = ''sim'' THEN 1 ELSE 0 END',
'        ) AS QTD_DISPOSITIVOS_AVC',
'',
'    FROM ADMIN.T_DISPOSITIVOS X',
'',
'    JOIN ADMIN.T_INTERNACOES I',
'        ON I.ID_INTERNACAO = X.ID_INTERNACAO',
'',
'    JOIN ADMIN.T_DIAGNOSTICOS D',
'        ON D.CID = I.CID',
'',
'    WHERE X.ID_INTERNACAO = :P4_ID_INTERNACAO',
'),',
'',
'CARDS AS (',
'',
'    SELECT',
'        ''Sonda Vesical'' AS TITULO,',
'',
'        CASE LOWER(SONDA_VESICAL_DE_DEMORA)',
'            WHEN ''sim'' THEN ''Sim''',
unistr('            WHEN ''nao'' THEN ''N\00E3o'''),
'            ELSE SONDA_VESICAL_DE_DEMORA',
'        END AS VALOR,',
'',
'        CASE',
'            WHEN PATOLOGIA <> ''ITU'' THEN ''NEUTRO''',
'            WHEN LOWER(SONDA_VESICAL_DE_DEMORA) = ''nao'' THEN ''VERDE''',
'            ELSE ''VERMELHO''',
'        END AS STATUS_COR,',
'',
'        1 AS ORDEM',
'',
'    FROM DADOS',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
'        ''SNG'',',
'',
'        CASE LOWER(SONDA_NASOGASTRICA)',
'            WHEN ''sim'' THEN ''Sim''',
unistr('            WHEN ''nao'' THEN ''N\00E3o'''),
'            ELSE SONDA_NASOGASTRICA',
'        END,',
'',
'        CASE',
'            WHEN PATOLOGIA <> ''AVC'' THEN ''NEUTRO''',
'            WHEN QTD_DISPOSITIVOS_AVC = 0 THEN ''VERDE''',
'            WHEN QTD_DISPOSITIVOS_AVC = 1 THEN ''AMARELO''',
'            ELSE ''VERMELHO''',
'        END,',
'',
'        2',
'',
'    FROM DADOS',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
'        ''SNE'',',
'',
'        CASE LOWER(SONDA_NASOENTERAL)',
'            WHEN ''sim'' THEN ''Sim''',
unistr('            WHEN ''nao'' THEN ''N\00E3o'''),
'            ELSE SONDA_NASOENTERAL',
'        END,',
'',
'        CASE',
'            WHEN PATOLOGIA <> ''AVC'' THEN ''NEUTRO''',
'            WHEN QTD_DISPOSITIVOS_AVC = 0 THEN ''VERDE''',
'            WHEN QTD_DISPOSITIVOS_AVC = 1 THEN ''AMARELO''',
'            ELSE ''VERMELHO''',
'        END,',
'',
'        3',
'',
'    FROM DADOS',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
unistr('        ''Oxig\00EAnio (O\2082)'','),
'',
'        CASE LOWER(CATETER_DE_O2)',
'            WHEN ''sim'' THEN ''Sim''',
unistr('            WHEN ''nao'' THEN ''N\00E3o'''),
'            ELSE CATETER_DE_O2',
'        END,',
'',
'        CASE',
'            WHEN PATOLOGIA = ''AVC''',
'             AND LOWER(CATETER_DE_O2) = ''nao''',
'                THEN ''VERDE''',
'',
'            WHEN PATOLOGIA = ''AVC''',
'                THEN ''VERMELHO''',
'',
'            WHEN PATOLOGIA IN (''ITU'',''PNEUMONIA'')',
'             AND LOWER(INTUBACAO_OROTRAQUEAL) = ''nao''',
'             AND LOWER(VENTILACAO_MECANICA) = ''nao''',
'             AND LOWER(CATETER_DE_O2) = ''nao''',
'                THEN ''VERDE''',
'',
'            WHEN PATOLOGIA IN (''ITU'',''PNEUMONIA'')',
'             AND LOWER(INTUBACAO_OROTRAQUEAL) = ''nao''',
'             AND LOWER(VENTILACAO_MECANICA) = ''nao''',
'             AND LOWER(CATETER_DE_O2) = ''sim''',
'                THEN ''AMARELO''',
'',
'            WHEN PATOLOGIA IN (''ITU'',''PNEUMONIA'')',
'                THEN ''VERMELHO''',
'',
'            ELSE ''NEUTRO''',
'        END,',
'',
'        4',
'',
'    FROM DADOS',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
'        ''IOT'',',
'',
'        CASE LOWER(INTUBACAO_OROTRAQUEAL)',
'            WHEN ''sim'' THEN ''Sim''',
unistr('            WHEN ''nao'' THEN ''N\00E3o'''),
'            ELSE INTUBACAO_OROTRAQUEAL',
'        END,',
'',
'        CASE',
'            WHEN PATOLOGIA = ''AVC''',
'             AND LOWER(INTUBACAO_OROTRAQUEAL) = ''nao''',
'             AND LOWER(VENTILACAO_MECANICA) = ''nao''',
'                THEN ''VERDE''',
'',
'            WHEN PATOLOGIA = ''AVC''',
'                THEN ''VERMELHO''',
'',
'            WHEN PATOLOGIA IN (''ITU'',''PNEUMONIA'')',
'             AND LOWER(INTUBACAO_OROTRAQUEAL) = ''nao''',
'             AND LOWER(VENTILACAO_MECANICA) = ''nao''',
'             AND LOWER(CATETER_DE_O2) = ''nao''',
'                THEN ''VERDE''',
'',
'            WHEN PATOLOGIA IN (''ITU'',''PNEUMONIA'')',
'             AND LOWER(INTUBACAO_OROTRAQUEAL) = ''nao''',
'             AND LOWER(VENTILACAO_MECANICA) = ''nao''',
'             AND LOWER(CATETER_DE_O2) = ''sim''',
'                THEN ''AMARELO''',
'',
'            WHEN PATOLOGIA IN (''ITU'',''PNEUMONIA'')',
'                THEN ''VERMELHO''',
'',
'            ELSE ''NEUTRO''',
'        END,',
'',
'        5',
'',
'    FROM DADOS',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
unistr('        ''Ventila\00E7\00E3o Mec\00E2nica'','),
'',
'        CASE LOWER(VENTILACAO_MECANICA)',
'            WHEN ''sim'' THEN ''Sim''',
unistr('            WHEN ''nao'' THEN ''N\00E3o'''),
'            ELSE VENTILACAO_MECANICA',
'        END,',
'',
'        CASE',
'            WHEN PATOLOGIA = ''AVC''',
'             AND LOWER(INTUBACAO_OROTRAQUEAL) = ''nao''',
'             AND LOWER(VENTILACAO_MECANICA) = ''nao''',
'                THEN ''VERDE''',
'',
'            WHEN PATOLOGIA = ''AVC''',
'                THEN ''VERMELHO''',
'',
'            WHEN PATOLOGIA IN (''ITU'',''PNEUMONIA'')',
'             AND LOWER(INTUBACAO_OROTRAQUEAL) = ''nao''',
'             AND LOWER(VENTILACAO_MECANICA) = ''nao''',
'             AND LOWER(CATETER_DE_O2) = ''nao''',
'                THEN ''VERDE''',
'',
'            WHEN PATOLOGIA IN (''ITU'',''PNEUMONIA'')',
'             AND LOWER(INTUBACAO_OROTRAQUEAL) = ''nao''',
'             AND LOWER(VENTILACAO_MECANICA) = ''nao''',
'             AND LOWER(CATETER_DE_O2) = ''sim''',
'                THEN ''AMARELO''',
'',
'            WHEN PATOLOGIA IN (''ITU'',''PNEUMONIA'')',
'                THEN ''VERMELHO''',
'',
'            ELSE ''NEUTRO''',
'        END,',
'',
'        6',
'',
'    FROM DADOS',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
'        ''CVC'',',
'',
'        CASE LOWER(CATETER_VENOSO_CENTRAL)',
'            WHEN ''sim'' THEN ''Sim''',
unistr('            WHEN ''nao'' THEN ''N\00E3o'''),
'            ELSE CATETER_VENOSO_CENTRAL',
'        END,',
'',
'        CASE',
'            WHEN PATOLOGIA = ''AVC''',
'             AND QTD_DISPOSITIVOS_AVC = 0',
'                THEN ''VERDE''',
'',
'            WHEN PATOLOGIA = ''AVC''',
'             AND QTD_DISPOSITIVOS_AVC = 1',
'                THEN ''AMARELO''',
'',
'            WHEN PATOLOGIA = ''AVC''',
'                THEN ''VERMELHO''',
'',
'            WHEN PATOLOGIA = ''ITU''',
'             AND LOWER(CATETER_VENOSO_CENTRAL) = ''nao''',
'             AND LOWER(PICC) = ''nao''',
'                THEN ''VERDE''',
'',
'            WHEN PATOLOGIA = ''ITU''',
'                THEN ''VERMELHO''',
'',
'            ELSE ''NEUTRO''',
'        END,',
'',
'        7',
'',
'    FROM DADOS',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
'        ''PICC'',',
'',
'        CASE LOWER(PICC)',
'            WHEN ''sim'' THEN ''Sim''',
unistr('            WHEN ''nao'' THEN ''N\00E3o'''),
'            ELSE PICC',
'        END,',
'',
'        CASE',
'            WHEN PATOLOGIA = ''AVC''',
'             AND QTD_DISPOSITIVOS_AVC = 0',
'                THEN ''VERDE''',
'',
'            WHEN PATOLOGIA = ''AVC''',
'             AND QTD_DISPOSITIVOS_AVC = 1',
'                THEN ''AMARELO''',
'',
'            WHEN PATOLOGIA = ''AVC''',
'                THEN ''VERMELHO''',
'',
'            WHEN PATOLOGIA = ''ITU''',
'             AND LOWER(CATETER_VENOSO_CENTRAL) = ''nao''',
'             AND LOWER(PICC) = ''nao''',
'                THEN ''VERDE''',
'',
'            WHEN PATOLOGIA = ''ITU''',
'                THEN ''VERMELHO''',
'',
'            ELSE ''NEUTRO''',
'        END,',
'',
'        8',
'',
'    FROM DADOS',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
unistr('        ''Cateter Perif\00E9rico'','),
'',
'        CASE LOWER(CATETER_VENOSO_PERIFERICO)',
'            WHEN ''sim'' THEN ''Sim''',
unistr('            WHEN ''nao'' THEN ''N\00E3o'''),
'            ELSE CATETER_VENOSO_PERIFERICO',
'        END,',
'',
'        ''NEUTRO'',',
'',
'        9',
'',
'    FROM DADOS',
')',
'',
'SELECT',
'    TITULO,',
'    VALOR,',
'',
'    CASE STATUS_COR',
'        WHEN ''VERDE''    THEN ''#DCFCE7''',
'        WHEN ''AMARELO''  THEN ''#FEF3C7''',
'        WHEN ''VERMELHO'' THEN ''#FEE2E2''',
'        ELSE ''#F3F4F6''',
'    END AS COR_FUNDO,',
'',
'    CASE STATUS_COR',
'        WHEN ''VERDE''    THEN ''#166534''',
'        WHEN ''AMARELO''  THEN ''#92400E''',
'        WHEN ''VERMELHO'' THEN ''#991B1B''',
'        ELSE ''#4B5563''',
'    END AS COR_TEXTO,',
'',
'    ORDEM',
'',
'FROM CARDS',
'',
'ORDER BY ORDEM;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
