wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10212815179682507)
,p_plug_name=>'Resultado DataCross'
,p_static_id=>'resultado'
,p_region_css_classes=>'margin-top-md'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc:margin-top-md'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>30
,p_plug_grid_column_span=>8
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    ''Score DataCross'' AS TITULO,',
'',
'    TO_CHAR(',
'        D.SCORE_ALTA,',
'        ''FM990D0'',',
'        ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'    ) || ''%'' AS VALOR,',
'',
'    D.DESTINO_SUGERIDO AS DESCRICAO,',
'',
'    CASE',
unistr('        WHEN D.DESTINO_SUGERIDO = ''Apto para transfer\00EAncia'''),
'            THEN ''Necessita continuidade hospitalar''',
'',
'        WHEN D.DESTINO_SUGERIDO = ''Apto para alta''',
'            THEN ''Sem necessidade de continuidade hospitalar''',
'',
'        WHEN D.DESTINO_SUGERIDO = ''Reavaliar em 24 horas''',
unistr('            THEN ''Reavalia\00E7\00E3o cl\00EDnica necess\00E1ria'''),
'',
'        WHEN D.DESTINO_SUGERIDO = ''Permanece internado''',
unistr('            THEN ''Manter interna\00E7\00E3o'''),
'',
unistr('        ELSE ''Sem classifica\00E7\00E3o'''),
'    END AS PONTOS,',
'',
'    CASE',
'        WHEN D.DESTINO_SUGERIDO IN (',
'            ''Apto para alta'',',
unistr('            ''Apto para transfer\00EAncia'''),
'        )',
'            THEN ''#E8F5E9''',
'',
'        WHEN D.DESTINO_SUGERIDO = ''Reavaliar em 24 horas''',
'            THEN ''#FFF8E1''',
'',
'        ELSE ''#FDECEC''',
'    END AS COR_FUNDO,',
'',
'    CASE',
'        WHEN D.DESTINO_SUGERIDO IN (',
'            ''Apto para alta'',',
unistr('            ''Apto para transfer\00EAncia'''),
'        )',
'            THEN ''#2E7D32''',
'',
'        WHEN D.DESTINO_SUGERIDO = ''Reavaliar em 24 horas''',
'            THEN ''#9A6700''',
'',
'        ELSE ''#B3261E''',
'    END AS COR_TEXTO',
'',
'FROM WKSP_DATACROSS.V_DECISAO_DATACROSS D',
'WHERE D.ID_INTERNACAO = :P4_ID_INTERNACAO;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20260910205839Z')
,p_updated_on=>wwv_flow_imp.dz('20260913212835Z')
,p_created_by=>'DATACROSS_APP'
,p_updated_by=>'DATACROSS_APP'
);
