,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    CASE',
'        WHEN S.BLOQUEIO = 1',
unistr('            THEN ''Bloqueio Cl\00EDnico'''),
unistr('        ELSE ''Sem Bloqueio Cl\00EDnico'''),
'    END AS TITULO,',
'',
'    CASE',
'        WHEN S.BLOQUEIO = 1',
unistr('            THEN NVL(S.MOTIVO_BLOQUEIO, ''Bloqueio cl\00EDnico identificado.'')'),
unistr('        ELSE ''Nenhum crit\00E9rio de bloqueio identificado para esta avalia\00E7\00E3o.'''),
'    END AS DESCRICAO,',
'',
'    CASE',
'        WHEN S.BLOQUEIO = 1',
unistr('            THEN ''Requer reavalia\00E7\00E3o antes de considerar alta, transfer\00EAncia ou reabilita\00E7\00E3o.'''),
unistr('        ELSE ''Paciente sem bloqueio cl\00EDnico pelo DataCross.'''),
'    END AS STATUS_CLINICO',
'',
'FROM V_SCORE_DATACROSS S',
'WHERE S.ID_INTERNACAO = :P4_ID_INTERNACAO'))
