wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10212292015682501)
,p_plug_name=>'Sinais Vitais'
,p_static_id=>'sinaisvitais'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>50
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH DADOS AS (',
'    SELECT',
'        S.*,',
'',
'        CASE',
'            WHEN LOWER(D.DOENCA_DETECTADA)',
'                 IN (''avc_isquemico'',''avc_hemorragico'')',
'                THEN ''AVC''',
'',
'            WHEN LOWER(D.DOENCA_DETECTADA) LIKE ''%trato urin%''',
'                THEN ''ITU''',
'',
'            WHEN LOWER(D.DOENCA_DETECTADA) = ''pneumonia''',
'                THEN ''PNEUMONIA''',
'        END AS PATOLOGIA',
'',
'    FROM ADMIN.T_SINAIS_VITAIS S',
'',
'    JOIN ADMIN.T_INTERNACOES I',
'        ON I.ID_INTERNACAO = S.ID_INTERNACAO',
'',
'    JOIN ADMIN.T_DIAGNOSTICOS D',
'        ON D.CID = I.CID',
'',
'    WHERE S.ID_INTERNACAO = :P4_ID_INTERNACAO',
')',
'',
'SELECT',
'    ''FC (bpm)'' AS TITULO,',
'    TO_CHAR(FC) || '' bpm'' AS VALOR,',
'',
'    CASE',
'        WHEN FC BETWEEN 60 AND 100 THEN ''#DCFCE7''',
'        WHEN FC BETWEEN 41 AND 59',
'          OR FC BETWEEN 101 AND 130 THEN ''#FEF3C7''',
'        ELSE ''#FEE2E2''',
'    END AS COR_FUNDO,',
'',
'    CASE',
'        WHEN FC BETWEEN 60 AND 100 THEN ''#166534''',
'        WHEN FC BETWEEN 41 AND 59',
'          OR FC BETWEEN 101 AND 130 THEN ''#92400E''',
'        ELSE ''#991B1B''',
'    END AS COR_TEXTO,',
'',
'    1 AS ORDEM',
'',
'FROM DADOS',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
'    ''FR (irpm)'',',
'    TO_CHAR(FR) || '' irpm'',',
'',
'    CASE',
'        WHEN FR BETWEEN 12 AND 20 THEN ''#DCFCE7''',
'        WHEN FR BETWEEN 9 AND 11',
'          OR FR BETWEEN 21 AND 24 THEN ''#FEF3C7''',
'        ELSE ''#FEE2E2''',
'    END,',
'',
'    CASE',
'        WHEN FR BETWEEN 12 AND 20 THEN ''#166534''',
'        WHEN FR BETWEEN 9 AND 11',
'          OR FR BETWEEN 21 AND 24 THEN ''#92400E''',
'        ELSE ''#991B1B''',
'    END,',
'',
'    2',
'',
'FROM DADOS',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
'    ''PAS (mmHg)'',',
'    TO_CHAR(PAS) || '' mmHg'',',
'',
'    CASE',
'        WHEN PAS BETWEEN 100 AND 139',
'            THEN ''#DCFCE7''',
'',
'        WHEN PATOLOGIA = ''AVC''',
'         AND (',
'             PAS BETWEEN 90 AND 99',
'             OR PAS BETWEEN 140 AND 179',
'         )',
'            THEN ''#FEF3C7''',
'',
'        WHEN PATOLOGIA IN (''ITU'',''PNEUMONIA'')',
'         AND PAS BETWEEN 90 AND 99',
'            THEN ''#FEF3C7''',
'',
'        ELSE ''#FEE2E2''',
'    END,',
'',
'    CASE',
'        WHEN PAS BETWEEN 100 AND 139',
'            THEN ''#166534''',
'',
'        WHEN PATOLOGIA = ''AVC''',
'         AND (',
'             PAS BETWEEN 90 AND 99',
'             OR PAS BETWEEN 140 AND 179',
'         )',
'            THEN ''#92400E''',
'',
'        WHEN PATOLOGIA IN (''ITU'',''PNEUMONIA'')',
'         AND PAS BETWEEN 90 AND 99',
'            THEN ''#92400E''',
'',
'        ELSE ''#991B1B''',
'    END,',
'',
'    3',
'',
'FROM DADOS',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
unistr('    ''Temperatura (\00B0C)'','),
'',
'    TO_CHAR(',
'        TEMP_AXILAR,',
'        ''FM990D0'',',
'        ''NLS_NUMERIC_CHARACTERS='''',.''''''',
unistr('    ) || '' \00B0C'','),
'',
'    CASE',
'        WHEN TEMP_AXILAR BETWEEN 36 AND 37.2 THEN ''#DCFCE7''',
'        WHEN TEMP_AXILAR BETWEEN 37.3 AND 37.9 THEN ''#FEF3C7''',
'        ELSE ''#FEE2E2''',
'    END,',
'',
'    CASE',
'        WHEN TEMP_AXILAR BETWEEN 36 AND 37.2 THEN ''#166534''',
'        WHEN TEMP_AXILAR BETWEEN 37.3 AND 37.9 THEN ''#92400E''',
'        ELSE ''#991B1B''',
'    END,',
'',
'    4',
'',
'FROM DADOS',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
unistr('    ''SpO\2082 (%)'','),
'    TO_CHAR(SPO2) || ''%'',',
'',
'    CASE',
'        WHEN SPO2 >= 95 THEN ''#DCFCE7''',
'        WHEN SPO2 BETWEEN 92 AND 94 THEN ''#FEF3C7''',
'        ELSE ''#FEE2E2''',
'    END,',
'',
'    CASE',
'        WHEN SPO2 >= 95 THEN ''#166534''',
'        WHEN SPO2 BETWEEN 92 AND 94 THEN ''#92400E''',
'        ELSE ''#991B1B''',
'    END,',
'',
'    5',
'',
'FROM DADOS',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
'    ''Escala de Glasgow'',',
'    TO_CHAR(NIVEL_CONSCIENCIA),',
'',
'    CASE',
'        WHEN NIVEL_CONSCIENCIA = 15 THEN ''#DCFCE7''',
'        WHEN NIVEL_CONSCIENCIA BETWEEN 13 AND 14 THEN ''#FEF3C7''',
'        ELSE ''#FEE2E2''',
'    END,',
'',
'    CASE',
'        WHEN NIVEL_CONSCIENCIA = 15 THEN ''#166534''',
'        WHEN NIVEL_CONSCIENCIA BETWEEN 13 AND 14 THEN ''#92400E''',
'        ELSE ''#991B1B''',
'    END,',
'',
'    6',
'',
'FROM DADOS',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
'    ''Diurese (mL/kg/h)'',',
'',
'    TO_CHAR(',
'        DIURESE,',
'        ''FM990D00'',',
'        ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'    ) || '' mL/kg/h'',',
'',
'    CASE',
'        WHEN DIURESE >= 0.5 THEN ''#DCFCE7''',
'        WHEN DIURESE >= 0.3 THEN ''#FEF3C7''',
'        ELSE ''#FEE2E2''',
'    END,',
'',
'    CASE',
'        WHEN DIURESE >= 0.5 THEN ''#166534''',
'        WHEN DIURESE >= 0.3 THEN ''#92400E''',
'        ELSE ''#991B1B''',
'    END,',
'',
'    7',
'',
'FROM DADOS',
'',
'',
'UNION ALL',
'',
'',
'SELECT',
'    ''Glicemia (mg/dL)'',',
'    TO_CHAR(GLICEMIA_CAPILAR) || '' mg/dL'',',
'',
'    CASE',
'        WHEN GLICEMIA_CAPILAR BETWEEN 70 AND 140 THEN ''#DCFCE7''',
'        WHEN GLICEMIA_CAPILAR BETWEEN 141 AND 180 THEN ''#FEF3C7''',
'        ELSE ''#FEE2E2''',
'    END,',
'',
'    CASE',
'        WHEN GLICEMIA_CAPILAR BETWEEN 70 AND 140 THEN ''#166534''',
'        WHEN GLICEMIA_CAPILAR BETWEEN 141 AND 180 THEN ''#92400E''',
'        ELSE ''#991B1B''',
'    END,',
'',
'    8',
'',
'FROM DADOS',
'',
'ORDER BY ORDEM;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20260910203529Z')
,p_updated_on=>wwv_flow_imp.dz('20260912011426Z')
,p_created_by=>'DATACROSS_APP'
,p_updated_by=>'DATACROSS_APP'
);
