wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10212612400682505)
,p_plug_name=>'Tratamentos e Exames'
,p_static_id=>'tratamentos'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>80
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH DADOS AS (',
'    SELECT',
'        T.*,',
'',
'        CASE',
'            WHEN LOWER(D.DOENCA_DETECTADA)',
'                 IN (''avc_isquemico'', ''avc_hemorragico'')',
'                THEN ''AVC''',
'',
'            WHEN LOWER(D.DOENCA_DETECTADA)',
'                 LIKE ''%trato urin%''',
'                THEN ''ITU''',
'',
'            WHEN LOWER(D.DOENCA_DETECTADA) = ''pneumonia''',
'                THEN ''PNEUMONIA''',
'        END AS PATOLOGIA',
'',
'    FROM ADMIN.T_TRATAMENTOS_EXAMES T',
'',
'    JOIN ADMIN.T_INTERNACOES I',
'        ON I.ID_INTERNACAO = T.ID_INTERNACAO',
'',
'    JOIN ADMIN.T_DIAGNOSTICOS D',
'        ON D.CID = I.CID',
'',
'    WHERE T.ID_INTERNACAO = :P4_ID_INTERNACAO',
'),',
'',
'CARDS AS (',
'',
'    /* =========================',
'       AVC',
'       ========================= */',
'',
'    SELECT',
'        ''Tomografia para AVC'' AS TITULO,',
'',
'        CASE',
'            WHEN LOWER(TC_POSITIVO_PARA_AVC) = ''sim''',
'                THEN ''Positiva''',
'',
unistr('            WHEN LOWER(TC_POSITIVO_PARA_AVC) IN (''nao'', ''n\00E3o'')'),
'                THEN ''Negativa''',
'',
'            ELSE',
'                INITCAP(',
'                    REPLACE(',
unistr('                        NVL(TC_POSITIVO_PARA_AVC, ''N\00E3o informado''),'),
'                        ''_'',',
'                        '' ''',
'                    )',
'                )',
'        END AS VALOR,',
'',
'        ''NEUTRO'' AS STATUS_COR,',
'',
'        1 AS ORDEM',
'',
'    FROM DADOS',
'    WHERE PATOLOGIA = ''AVC''',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
'        ''Eletroencefalograma (EEG)'',',
'',
'        CASE',
'            WHEN LOWER(EEG_POSITIVO_PARA_AVC) = ''sim''',
'                THEN ''Positivo''',
'',
unistr('            WHEN LOWER(EEG_POSITIVO_PARA_AVC) IN (''nao'', ''n\00E3o'')'),
'                THEN ''Negativo''',
'',
'            ELSE',
'                INITCAP(',
'                    REPLACE(',
unistr('                        NVL(EEG_POSITIVO_PARA_AVC, ''N\00E3o informado''),'),
'                        ''_'',',
'                        '' ''',
'                    )',
'                )',
'        END,',
'',
'        ''NEUTRO'',',
'',
'        2',
'',
'    FROM DADOS',
'    WHERE PATOLOGIA = ''AVC''',
'',
'',
'    /* =========================',
'       ITU',
'       ========================= */',
'',
'    UNION ALL',
'',
'',
'    SELECT',
unistr('        ''Antibi\00F3tico'','),
'',
'        CASE',
'            WHEN LOWER(ANTIBIOTICO) = ''sim''',
'                THEN ''Em tratamento''',
'',
'            ELSE',
unistr('                ''N\00E3o registrado'''),
'        END,',
'',
'        CASE',
'            WHEN LOWER(ANTIBIOTICO) = ''sim''',
'                THEN ''AMARELO''',
'',
'            ELSE',
'                ''VERMELHO''',
'        END,',
'',
'        10',
'',
'    FROM DADOS',
'    WHERE PATOLOGIA = ''ITU''',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
unistr('        ''Tempo de antibi\00F3tico'','),
'',
'        CASE',
'            WHEN DURACAO_ATB_DIAS IS NOT NULL',
'                THEN TO_CHAR(DURACAO_ATB_DIAS) || '' dias''',
'',
'            ELSE',
unistr('                ''N\00E3o informado'''),
'        END,',
'',
'        CASE',
'            WHEN LOWER(ANTIBIOTICO) <> ''sim''',
'                THEN ''VERMELHO''',
'',
'            WHEN DURACAO_ATB_DIAS >= 3',
'                THEN ''VERDE''',
'',
'            WHEN DURACAO_ATB_DIAS > 0',
'                THEN ''AMARELO''',
'',
'            ELSE',
'                ''VERMELHO''',
'        END,',
'',
'        11',
'',
'    FROM DADOS',
'    WHERE PATOLOGIA = ''ITU''',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
'        ''Urocultura'',',
'',
'        CASE',
unistr('            WHEN LOWER(UROCULTURA) IN (''nao'', ''n\00E3o'')'),
unistr('                THEN ''N\00E3o registrada'''),
'',
'            ELSE',
'                INITCAP(',
'                    REPLACE(',
unistr('                        NVL(UROCULTURA, ''N\00E3o informado''),'),
'                        ''_'',',
'                        '' ''',
'                    )',
'                )',
'        END,',
'',
'        ''NEUTRO'',',
'',
'        12',
'',
'    FROM DADOS',
'    WHERE PATOLOGIA = ''ITU''',
'',
'',
'    /* =========================',
'       PNEUMONIA',
'       ========================= */',
'',
'    UNION ALL',
'',
'',
'    SELECT',
unistr('        ''Antibi\00F3tico'','),
'',
'        CASE',
'            WHEN LOWER(ANTIBIOTICO) = ''sim''',
'                THEN ''Em tratamento''',
'',
'            WHEN LOWER(ETIOLOGIA_PNEUMONIA) = ''bacteriana''',
unistr('                THEN ''N\00E3o registrado'''),
'',
'            ELSE',
unistr('                ''N\00E3o aplic\00E1vel / n\00E3o definido'''),
'        END,',
'',
'        CASE',
'            WHEN LOWER(ETIOLOGIA_PNEUMONIA) = ''bacteriana''',
'             AND LOWER(ANTIBIOTICO) = ''sim''',
'                THEN ''AMARELO''',
'',
'            WHEN LOWER(ETIOLOGIA_PNEUMONIA) = ''bacteriana''',
'                THEN ''VERMELHO''',
'',
'            ELSE',
'                ''NEUTRO''',
'        END,',
'',
'        20',
'',
'    FROM DADOS',
'    WHERE PATOLOGIA = ''PNEUMONIA''',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
unistr('        ''Tempo de antibi\00F3tico'','),
'',
'        CASE',
'            WHEN DURACAO_ATB_DIAS IS NOT NULL',
'                THEN TO_CHAR(DURACAO_ATB_DIAS) || '' dias''',
'',
'            ELSE',
unistr('                ''N\00E3o aplic\00E1vel'''),
'        END,',
'',
'        CASE',
'            WHEN LOWER(ETIOLOGIA_PNEUMONIA) <> ''bacteriana''',
'                THEN ''NEUTRO''',
'',
'            WHEN LOWER(ANTIBIOTICO) <> ''sim''',
'                THEN ''VERMELHO''',
'',
'            WHEN DURACAO_ATB_DIAS >= 5',
'                THEN ''VERDE''',
'',
'            WHEN DURACAO_ATB_DIAS > 0',
'                THEN ''AMARELO''',
'',
'            ELSE',
'                ''VERMELHO''',
'        END,',
'',
'        21',
'',
'    FROM DADOS',
'    WHERE PATOLOGIA = ''PNEUMONIA''',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
unistr('        ''Padr\00E3o de imagem'','),
'',
'        CASE',
'            WHEN PADRAO_TOMOGRAFIA IS NULL',
unistr('                THEN ''N\00E3o informado'''),
'',
'            ELSE',
'                INITCAP(',
'                    REPLACE(',
'                        PADRAO_TOMOGRAFIA,',
'                        ''_'',',
'                        '' ''',
'                    )',
'                )',
'        END,',
'',
'        CASE',
'',
'            WHEN LOWER(PADRAO_TOMOGRAFIA)',
'                 LIKE ''%cavita%''',
'                THEN ''VERMELHO''',
'',
'            WHEN LOWER(PADRAO_TOMOGRAFIA)',
'                 = ''sinal do halo''',
'                THEN ''VERMELHO''',
'',
'            WHEN LOWER(PADRAO_TOMOGRAFIA)',
'                 LIKE ''%consolida%''',
'                THEN ''AMARELO''',
'',
'            WHEN LOWER(PADRAO_TOMOGRAFIA)',
'                 LIKE ''%vidro fosco%''',
'                THEN ''AMARELO''',
'',
'            WHEN LOWER(PADRAO_TOMOGRAFIA)',
unistr('                 LIKE ''%n\00F3dulos centrolobulares%'''),
'                THEN ''AMARELO''',
'',
'            WHEN LOWER(PADRAO_TOMOGRAFIA)',
unistr('                 LIKE ''%\00E1rvore em brotamento%'''),
'                THEN ''AMARELO''',
'',
'            WHEN LOWER(PADRAO_TOMOGRAFIA)',
unistr('                 LIKE ''%pavimenta\00E7\00E3o%'''),
'                THEN ''AMARELO''',
'',
'            WHEN LOWER(PADRAO_TOMOGRAFIA)',
'                 LIKE ''%halo invertido%''',
'                THEN ''NEUTRO''',
'',
'            ELSE',
'                ''NEUTRO''',
'        END,',
'',
'        22',
'',
'    FROM DADOS',
'    WHERE PATOLOGIA = ''PNEUMONIA''',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
'        ''Etiologia da pneumonia'',',
'',
'        CASE LOWER(ETIOLOGIA_PNEUMONIA)',
'',
'            WHEN ''bacteriana''',
'                THEN ''Bacteriana''',
'',
'            WHEN ''viral''',
'                THEN ''Viral''',
'',
'            WHEN ''fungica''',
unistr('                THEN ''F\00FAngica'''),
'',
'            WHEN ''nao_especificada''',
unistr('                THEN ''N\00E3o especificada'''),
'',
'            ELSE',
'                INITCAP(',
'                    REPLACE(',
unistr('                        NVL(ETIOLOGIA_PNEUMONIA, ''N\00E3o informada''),'),
'                        ''_'',',
'                        '' ''',
'                    )',
'                )',
'        END,',
'',
'        CASE',
'            WHEN LOWER(ETIOLOGIA_PNEUMONIA) = ''nao_especificada''',
'                THEN ''AMARELO''',
'',
'            ELSE',
'                ''NEUTRO''',
'        END,',
'',
'        23',
'',
'    FROM DADOS',
'    WHERE PATOLOGIA = ''PNEUMONIA''',
'',
'',
'    UNION ALL',
'',
'',
'    SELECT',
unistr('        ''Tratamento etiol\00F3gico'','),
'',
'        CASE LOWER(TRATAMENTO_ETIOLOGICO)',
'',
'            WHEN ''antibiotico''',
unistr('                THEN ''Antibi\00F3tico'''),
'',
'            WHEN ''antifungico''',
unistr('                THEN ''Antif\00FAngico'''),
'',
'            WHEN ''antiviral_quando_indicado''',
'                THEN ''Antiviral quando indicado''',
'',
'            WHEN ''a_definir_apos_identificacao_etiologica''',
unistr('                THEN ''A definir ap\00F3s identifica\00E7\00E3o etiol\00F3gica'''),
'',
'            ELSE',
'                INITCAP(',
'                    REPLACE(',
unistr('                        NVL(TRATAMENTO_ETIOLOGICO, ''N\00E3o informado''),'),
'                        ''_'',',
'                        '' ''',
'                    )',
'                )',
'        END,',
'',
'        CASE',
'            WHEN LOWER(ETIOLOGIA_PNEUMONIA) = ''bacteriana''',
'             AND LOWER(TRATAMENTO_ETIOLOGICO) = ''antibiotico''',
'                THEN ''VERDE''',
'',
'            WHEN LOWER(ETIOLOGIA_PNEUMONIA) = ''fungica''',
'             AND LOWER(TRATAMENTO_ETIOLOGICO) = ''antifungico''',
'                THEN ''VERDE''',
'',
'            WHEN LOWER(ETIOLOGIA_PNEUMONIA) = ''viral''',
'             AND LOWER(TRATAMENTO_ETIOLOGICO)',
'                 = ''antiviral_quando_indicado''',
'                THEN ''AMARELO''',
'',
'            WHEN LOWER(ETIOLOGIA_PNEUMONIA) = ''nao_especificada''',
'             AND LOWER(TRATAMENTO_ETIOLOGICO)',
'                 = ''a_definir_apos_identificacao_etiologica''',
'                THEN ''AMARELO''',
'',
'            ELSE',
'                ''VERMELHO''',
'        END,',
'',
'        24',
'',
'    FROM DADOS',
'    WHERE PATOLOGIA = ''PNEUMONIA''',
')',
'',
'SELECT',
'    TITULO,',
'    VALOR,',
'',
'    CASE STATUS_COR',
'        WHEN ''VERDE''    THEN ''#DCFCE7''',
'        WHEN ''AMARELO''  THEN ''#FEF3C7''',
'        WHEN ''VERMELHO'' THEN ''#FEE2E2''',
'        ELSE ''#F3F4F6''',
'    END AS COR_FUNDO,',
'',
'    CASE STATUS_COR',
'        WHEN ''VERDE''    THEN ''#166534''',
'        WHEN ''AMARELO''  THEN ''#92400E''',
'        WHEN ''VERMELHO'' THEN ''#991B1B''',
'        ELSE ''#4B5563''',
'    END AS COR_TEXTO,',
'',
'    ORDEM',
'',
'FROM CARDS',
'',
'ORDER BY ORDEM;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
