,p_name=>unistr('Resumo da Avalia\00E7\00E3o')
,p_static_id=>unistr('resumo-da-avalia\00E7\00E3o')
,p_template=>4073835273271169698
,p_display_sequence=>40
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_new_grid_row=>false
,p_new_grid_column=>false
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    I.ID_PACIENTE AS PACIENTE,',
'',
'    CASE',
'        WHEN H.NOME_HOSPITAL =',
'             ''hospital_universitario_sr._dolphin_sakila''',
unistr('        THEN ''Hospital Universit\00E1rio Sr. Dolphin Sakila'''),
'        ELSE INITCAP(REPLACE(H.NOME_HOSPITAL, ''_'', '' ''))',
'    END AS HOSPITAL,',
'',
'    CASE',
'        WHEN LOWER(DG.DOENCA_DETECTADA) = ''avc_isquemico''',
unistr('            THEN ''AVC Isqu\00EAmico'''),
'',
'        WHEN LOWER(DG.DOENCA_DETECTADA) = ''avc_hemorragico''',
unistr('            THEN ''AVC Hemorr\00E1gico'''),
'',
'        WHEN LOWER(DG.DOENCA_DETECTADA) = ''pneumonia''',
'            THEN ''Pneumonia''',
'',
'        WHEN LOWER(DG.DOENCA_DETECTADA) LIKE ''%trato urin%''',
unistr('            THEN ''Infec\00E7\00E3o do Trato Urin\00E1rio (ITU)'''),
'',
'        ELSE INITCAP(',
'            REPLACE(DG.DOENCA_DETECTADA, ''_'', '' '')',
'        )',
'    END AS PATOLOGIA,',
'',
'    I.TEMPO_PERMANENCIA_DIAS AS DIAS_INTERNADO,',
'',
'',
'    /* ============================',
unistr('       SCORE \00DANICO DATACROSS'),
'       ============================ */',
'',
'    TO_CHAR(',
'        DC.SCORE_ALTA,',
'        ''FM990D0'',',
'        ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'    ) || ''%'' AS SCORE,',
'',
'',
'    /* ============================',
unistr('       NOVA SUGEST\00C3O DATACROSS'),
'       ============================ */',
'',
'    DC.DESTINO_SUGERIDO,',
'',
'',
unistr('    /* Mant\00E9m os pontos do score original */'),
'    TO_CHAR(S.PONTOS_OBTIDOS)',
'        || '' de ''',
'        || TO_CHAR(S.PONTOS_APLICAVEIS) AS PONTOS,',
'',
'',
'    /* ============================',
unistr('       BLOQUEIO CL\00CDNICO'),
'       ============================ */',
'',
'    CASE',
'        WHEN DC.BLOQUEIO_ALTA = 1',
'        THEN ''Sim''',
unistr('        ELSE ''N\00E3o'''),
'    END AS BLOQUEIO_CLINICO,',
'',
'',
'    CASE',
'        WHEN DC.BLOQUEIO_ALTA = 1',
'        THEN NVL(',
'            DC.MOTIVO_BLOQUEIO_ALTA,',
unistr('            ''Crit\00E9rio de seguran\00E7a identificado.'''),
'        )',
'        ELSE',
unistr('            ''Nenhum bloqueio cl\00EDnico identificado.'''),
'    END AS MOTIVO_BLOQUEIO,',
'',
'',
'    /* ============================',
'       CONTINUIDADE HOSPITALAR',
'       ============================ */',
'',
'    DC.NECESSIDADE_CONTINUIDADE_HOSPITALAR,',
'',
'',
'    /* ============================',
unistr('       ALERTA DE TRANSFER\00CANCIA'),
'       ============================ */',
'',
'    CASE',
'        WHEN DC.ALERTA_CRITICO_TRANSFERENCIA = 1',
'        THEN ''Sim''',
unistr('        ELSE ''N\00E3o'''),
'    END AS ALERTA_CRITICO_TRANSFERENCIA',
'',
'',
'FROM ADMIN.T_INTERNACOES I',
'',
'JOIN ADMIN.T_HOSPITAIS H',
'    ON H.ID_HOSPITAL = I.ID_HOSPITAL',
'',
'JOIN ADMIN.T_DIAGNOSTICOS DG',
'    ON DG.CID = I.CID',
'',
'JOIN WKSP_DATACROSS.V_SCORE_DATACROSS S',
'    ON S.ID_INTERNACAO = I.ID_INTERNACAO',
'',
'JOIN WKSP_DATACROSS.V_DECISAO_DATACROSS DC',
'    ON DC.ID_INTERNACAO = I.ID_INTERNACAO',
'',
'WHERE I.ID_INTERNACAO = :P5_ID_INTERNACAO;'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'Y'
,p_prn_format=>'PDF'
,p_prn_output_link_text=>'Print'
