prompt --application/pages/page_00006
begin
wwv_flow_imp_page.create_page(
 p_id=>6
,p_name=>'Auditoria'
,p_alias=>'AUDITORIA'
,p_step_title=>'Auditoria'
,p_autocomplete_on_off=>'OFF'
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'18'
,p_created_on=>wwv_flow_imp.dz('20260910214928Z')
,p_last_updated_on=>wwv_flow_imp.dz('20260913222236Z')
,p_created_by=>'DATACROSS_APP'
,p_last_updated_by=>'DATACROSS_APP'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10241732936139168)
,p_plug_name=>'Auditoria'
,p_static_id=>'auditoria'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    V.ID_VALIDACAO,',
'',
'    V.ID_INTERNACAO,',
'',
'    I.ID_PACIENTE,',
'',
'    CASE',
'        WHEN H.NOME_HOSPITAL =',
'             ''hospital_universitario_sr._dolphin_sakila''',
unistr('        THEN ''Hospital Universit\00E1rio Sr. Dolphin Sakila'''),
'',
'        ELSE INITCAP(',
'            REPLACE(H.NOME_HOSPITAL, ''_'', '' '')',
'        )',
'    END AS HOSPITAL,',
'',
'    CASE',
'        WHEN LOWER(DG.DOENCA_DETECTADA) = ''avc_isquemico''',
unistr('        THEN ''AVC Isqu\00EAmico'''),
'',
'        WHEN LOWER(DG.DOENCA_DETECTADA) = ''avc_hemorragico''',
unistr('        THEN ''AVC Hemorr\00E1gico'''),
'',
'        WHEN LOWER(DG.DOENCA_DETECTADA) LIKE ''%trato urin%''',
unistr('        THEN ''Infec\00E7\00E3o do Trato Urin\00E1rio'''),
'',
'        WHEN LOWER(DG.DOENCA_DETECTADA) = ''pneumonia''',
'        THEN ''Pneumonia''',
'',
'        ELSE INITCAP(',
'            REPLACE(DG.DOENCA_DETECTADA, ''_'', '' '')',
'        )',
'    END AS PATOLOGIA,',
'',
'',
'    /* ============================',
'       SCORE DATACROSS',
'       ============================ */',
'',
'    DC.SCORE_ALTA AS SCORE,',
'',
'',
'    /* ============================',
unistr('       SUGEST\00C3O DO DATACROSS'),
'       ============================ */',
'',
'    DC.DESTINO_SUGERIDO,',
'',
'',
'    /* ============================',
unistr('       DECIS\00C3O M\00C9DICA'),
'       ============================ */',
'',
'    CASE',
'        WHEN V.DECISAO = ''APROVAR_SUGESTAO''',
unistr('        THEN ''Aprovar sugest\00E3o'''),
'',
'        WHEN V.DECISAO = ''CONTESTAR''',
'        THEN ''Contestar''',
'',
'        WHEN V.DECISAO = ''REDIRECIONAR''',
'        THEN ''Redirecionar''',
'',
'        ELSE INITCAP(',
'            REPLACE(V.DECISAO, ''_'', '' '')',
'        )',
'    END AS DECISAO_MEDICA,',
'',
'',
'    /* ============================',
'       NOVO DESTINO',
'',
unistr('       S\00F3 aparece quando o m\00E9dico'),
'       redirecionou o caso.',
'       ============================ */',
'',
'    CASE',
'        WHEN V.NOVO_DESTINO = ''ALTA''',
'        THEN ''Alta''',
'',
'        WHEN V.NOVO_DESTINO = ''TRANSFERENCIA''',
unistr('        THEN ''Transfer\00EAncia'''),
'',
'        WHEN V.NOVO_DESTINO = ''REABILITACAO''',
unistr('        THEN ''Reabilita\00E7\00E3o'''),
'',
'        WHEN V.NOVO_DESTINO = ''PERMANECER_INTERNADO''',
'        THEN ''Permanecer internado''',
'',
'        WHEN V.NOVO_DESTINO IS NULL',
'        THEN NULL',
'',
'        ELSE INITCAP(',
'            REPLACE(V.NOVO_DESTINO, ''_'', '' '')',
'        )',
'    END AS NOVO_DESTINO,',
'',
'',
'    /* ============================',
'       JUSTIFICATIVA / AUDITORIA',
'       ============================ */',
'',
'    V.JUSTIFICATIVA,',
'',
'    V.USUARIO_APEX AS PROFISSIONAL,',
'',
'    V.DT_VALIDACAO AS DATA_VALIDACAO,',
'',
'',
'    /* ============================',
'       STATUS ATUAL',
'       ============================ */',
'',
'    CASE',
'        WHEN LOWER(TRIM(I.STATUS)) = ''internado''',
'        THEN ''Internado''',
'',
'        WHEN LOWER(TRIM(I.STATUS)) = ''alta''',
'        THEN ''Alta''',
'',
'        WHEN LOWER(TRIM(I.STATUS)) = ''transferido''',
'        THEN ''Transferido''',
'',
'        WHEN LOWER(TRIM(I.STATUS)) = ''obito''',
unistr('        THEN ''\00D3bito'''),
'',
'        ELSE INITCAP(',
'            REPLACE(I.STATUS, ''_'', '' '')',
'        )',
'    END AS STATUS_ATUAL',
'',
'',
'FROM WKSP_DATACROSS.T_VALIDACAO_MEDICA V',
'',
'LEFT JOIN ADMIN.T_INTERNACOES I',
'    ON I.ID_INTERNACAO = V.ID_INTERNACAO',
'',
'LEFT JOIN ADMIN.T_HOSPITAIS H',
'    ON H.ID_HOSPITAL = I.ID_HOSPITAL',
'',
'LEFT JOIN ADMIN.T_DIAGNOSTICOS DG',
'    ON DG.CID = I.CID',
'',
'LEFT JOIN WKSP_DATACROSS.V_DECISAO_DATACROSS DC',
'    ON DC.ID_INTERNACAO = V.ID_INTERNACAO',
'',
'',
'ORDER BY',
'    V.DT_VALIDACAO DESC,',
'    V.ID_VALIDACAO DESC;'))
